// Interleaved A/B frame-time measurement over CDP.
// Usage: node frames.mjs <rounds> <label::url> <label::url> ...
// Each visit settles, then times 90 consecutive animation frames and reports their median.
import { spawn } from 'node:child_process'
import { setTimeout as sleep } from 'node:timers/promises'

const [, , roundsArg, ...targets] = process.argv
const rounds = Number(roundsArg)
const WIDTH = 1600
const HEIGHT = 1000
const SETTLE_MS = Number(process.env.SETTLE_MS ?? 20000)
const FRAMES = Number(process.env.FRAMES ?? 90)
const PORT = Number(process.env.CDP_PORT ?? 9873)

// A debugging port that already answers belongs to someone else's browser;
// driving it would both corrupt this run and theirs.
try {
  const probe = await fetch(`http://127.0.0.1:${PORT}/json/version`, { signal: AbortSignal.timeout(1500) })
  if (probe.ok) throw new Error(`port ${PORT} is already a devtools endpoint`)
} catch (error) {
  if (String(error).includes('already a devtools endpoint')) throw error
}

const chrome = spawn('/opt/pw-browsers/chromium', [
  '--headless=new',
  '--no-sandbox',
  '--disable-dev-shm-usage',
  '--enable-unsafe-swiftshader',
  '--hide-scrollbars',
  '--force-device-scale-factor=1',
  `--window-size=${WIDTH},${HEIGHT}`,
  `--remote-debugging-port=${PORT}`,
  'about:blank',
], { stdio: ['ignore', 'pipe', 'pipe'] })
chrome.stderr.on('data', () => {})

async function firstPage() {
  for (let attempt = 0; attempt < 60; attempt++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json()
      const page = list.find(t => t.type === 'page')
      if (page) return page
    } catch {}
    await sleep(400)
  }
  throw new Error('chromium devtools never came up')
