// Usage: node shoot-opening.mjs <outDir> <url> [prefix]
import { spawn } from 'node:child_process'
import { writeFileSync, mkdirSync } from 'node:fs'
import { setTimeout as sleep } from 'node:timers/promises'

const [, , outDir, url, prefix = 'open'] = process.argv
const WIDTH = 1600
const HEIGHT = 1000
const PORT = Number(process.env.CDP_PORT ?? 9342)
const REDUCED = process.env.REDUCED === '1'
mkdirSync(outDir, { recursive: true })

try {
  const probe = await fetch(`http://127.0.0.1:${PORT}/json/version`, { signal: AbortSignal.timeout(1500) })
  if (probe.ok) throw new Error(`port ${PORT} is already a devtools endpoint`)
} catch (error) {
  if (String(error).includes('already a devtools endpoint')) throw error
}

const chrome = spawn('/opt/pw-browsers/chromium', [
  '--headless=new',
  '--no-sandbox',
  '--disable-dev-shm-usage',
  '--enable-unsafe-swiftshader',
  '--hide-scrollbars',
  '--force-device-scale-factor=1',
  `--window-size=${WIDTH},${HEIGHT}`,
  `--remote-debugging-port=${PORT}`,
  'about:blank',
], { stdio: ['ignore', 'pipe', 'pipe'] })
chrome.stderr.on('data', () => {})

async function firstPage() {
  for (let attempt = 0; attempt < 60; attempt++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json()
      const page = list.find(t => t.type === 'page')
      if (page) return page
    } catch {}
    await sleep(400)
  }
  throw new Error('chromium devtools never came up')
}

const page = await firstPage()
const ws = new WebSocket(page.webSocketDebuggerUrl)
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true })
  ws.addEventListener('error', reject, { once: true })
})

let nextId = 0
const pending = new Map()
const events = new Map()
ws.addEventListener('message', (message) => {
  const payload = JSON.parse(message.data)
  if (payload.id !== undefined) {
    const entry = pending.get(payload.id)
    pending.delete(payload.id)
    if (entry) entry.resolve(payload.result ?? payload.error)
    return
  }
  const waiters = events.get(payload.method) ?? []
  events.set(payload.method, [])
  for (const waiter of waiters) waiter(payload.params)
})

function send(method, params = {}) {
  const id = ++nextId
  return new Promise((resolve) => {
    pending.set(id, { resolve })
    ws.send(JSON.stringify({ id, method, params }))
  })
}

function once(method, timeoutMs = 40000) {
  return new Promise((resolve) => {
    const list = events.get(method) ?? []
    list.push(resolve)
    events.set(method, list)
    setTimeout(() => resolve(undefined), timeoutMs)
  })
}

await send('Page.enable')
await send('Runtime.enable')
if (REDUCED) {
  await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'reduce' }] })
}
await send('Emulation.setDeviceMetricsOverride', { width: WIDTH, height: HEIGHT, deviceScaleFactor: 1, mobile: false })

const loaded = once('Page.loadEventFired')
await send('Page.navigate', { url })
await loaded
await sleep(18000)

async function shot(name) {
  const result = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false })
  if (!result?.data) { console.error(name, 'no data'); return }
  writeFileSync(`${outDir}/${prefix}-${name}.png`, Buffer.from(result.data, 'base64'))
  const state = await send('Runtime.evaluate', {
    expression: `JSON.stringify({ beat: document.querySelector('.opening')?.dataset.beat ?? null, phase: document.querySelector('.deck')?.dataset.opening, counts: [...document.querySelectorAll('.count b')].map(e => e.innerText) })`,
    returnByValue: true,
  })
  console.log(`${prefix}-${name}.png`, state?.result?.value ?? '')
}

await send('Runtime.evaluate', { expression: `window.dispatchEvent(new KeyboardEvent('keydown', { key: 'o' }))` })
await sleep(2200); await shot('1-claim')
await sleep(6000); await shot('2-ignition')
await sleep(4500); await shot('3-late')
await sleep(6500); await shot('4-settled')

ws.close()
chrome.kill('SIGKILL')
process.exit(0)

